fn to_json<T: serde::Serialize>(value: &T) -> ServiceResult<Value> {
    serde_json::to_value(value).map_err(|e| ServiceError::Internal(e.to_string()))
}

#[allow(dead_code)]
fn record_id(call: &Call<'_>) -> ServiceResult<String> {
    call.id.clone().ok_or_else(|| ServiceError::Validation(format!("step `{}` names no record", call.step)))
}

/// The parameters of a step as fields to write: everything but the record's `id`.
#[allow(dead_code)]
fn fields_of(params: &Value) -> HashMap<String, Value> {
    params.as_object().cloned().unwrap_or_default().into_iter().filter(|(k, _)| k != "id").collect()
}

/// The parameters of a `query` or `fetch` as equality filters, a page size and a sort.
#[allow(dead_code)]
fn filters_of(params: &Value, default_limit: u32) -> (HashMap<String, String>, u32) {
    let mut filters = HashMap::new();
    let mut limit = default_limit;
    for (k, v) in params.as_object().into_iter().flatten() {
        match k.as_str() {
            "_limit" => limit = v.as_u64().map(|n| n as u32).unwrap_or(default_limit),
            "_order" => {
                // `created_at DESC` is the filter map's `sort=-created_at`.
                let text = v.as_str().unwrap_or_default();
                let mut parts = text.split_whitespace();
                if let Some(field) = parts.next() {
                    let desc = parts.next().is_some_and(|d| d.eq_ignore_ascii_case("desc"));
                    filters.insert("sort".to_string(), format!("{}{field}", if desc { "-" } else { "" }));
                }
            }
            _ => {
                let text = match v { Value::String(s) => s.clone(), other => other.to_string() };
                filters.insert(k.clone(), text);
            }
        }
    }
    (filters, limit)
}

